{
  "cleanUrls": true,
  "trailingSlash": false,
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        { "key": "X-Frame-Options", "value": "DENY" },
        { "key": "X-Content-Type-Options", "value": "nosniff" },
        { "key": "Cross-Origin-Opener-Policy", "value": "same-origin" },
        { "key": "Referrer-Policy", "value": "strict-origin-when-cross-origin" },
        { "key": "Permissions-Policy", "value": "camera=(), microphone=(), geolocation=()" }
      ]
    },
    {
      "source": "/assets/fonts/(.*)",
      "headers": [
        { "key": "Cache-Control", "value": "public, max-age=31536000, immutable" }
      ]
    },
    {
      "source": "/(reset.css|style.css|main.js)",
      "headers": [
        { "key": "Cache-Control", "value": "public, max-age=86400, must-revalidate" }
      ]
    },
    {
      "source": "/public/(.*).pdf",
      "headers": [
        { "key": "Content-Disposition", "value": "attachment" },
        { "key": "Cache-Control", "value": "public, max-age=86400, must-revalidate" }
      ]
    }
  ]
}

document.addEventListener('DOMContentLoaded', () => {
  if (typeof lucide !== 'undefined') lucide.createIcons();
});

document.addEventListener('alpine:initialized', () => {
  if (typeof lucide !== 'undefined') lucide.createIcons();
});

document.addEventListener('alpine:init', () => {
  Alpine.data('portfolio', () => ({
    mode: 'developer',
    aboutOpen: false,

    modes: ['developer', 'researcher', 'creative'],

    setMode(m) {
      this.mode = m;
    },

    projects: {
      developer: [
        { name: 'F9S', desc: 'Low-level systems runtime targeting bare metal x64.', lang: 'C / NASM' },
        { name: 'SympJS', desc: 'Symbolic algebra engine for the browser.', lang: 'TypeScript' },
        { name: 'Word of God', desc: 'Esolang where every program is a scripture verse.', lang: 'Esolang / C' },
        { name: 'Kaali', desc: 'Compiler frontend with a hand-written parser.', lang: 'Go' },
        { name: 'PeppertinCSS', desc: 'Classless CSS baseline. No utility bloat.', lang: 'CSS' },
      ],
      researcher: [
        { name: 'OpenRecords', desc: 'Corpus ingestion pipeline for NLP datasets.', lang: 'Python' },
        { name: 'Literary Pipeline', desc: 'PDF-to-structured-text for literary corpora.', lang: 'Python / RAG' },
        { name: 'NeonGPT', desc: 'Fine-tuning experiments on creative generation.', lang: 'Python / PyTorch' },
      ],
      creative: [
        { name: 'Apocrypha Series', desc: 'Speculative fiction rooted in flood theology.', lang: 'Fiction' },
        { name: 'Word of God', desc: 'Esolang as liturgy — code as sacred text.', lang: 'Esolang' },
        { name: 'Dozhlang', desc: 'Constructed language for the Apocrypha world.', lang: 'Conlang' },
      ],
    },

    skills: {
      developer: [
        { group: 'Systems', items: ['C', 'C++', 'NASM', 'Go'] },
        { group: 'Web', items: ['TypeScript', 'Svelte', 'Alpine.js'] },
        { group: 'Tooling', items: ['esbuild', 'Git', 'Linux'] },
      ],
      researcher: [
        { group: 'ML / AI', items: ['RAG', 'BPE tokenizer', 'fine-tuning', 'PyTorch'] },
        { group: 'Data', items: ['PDF pipelines', 'parallel processing', 'corpus curation'] },
        { group: 'Languages', items: ['Python', 'Go'] },
      ],
      creative: [
        { group: 'Writing', items: ['worldbuilding', 'theology', 'angelology'] },
        { group: 'Language', items: ['conlang design', 'esolang design', 'liturgical grammar'] },
        { group: 'Themes', items: ['apocrypha', 'flood mythology', 'divine horror'] },
      ],
    },

    about: {
      developer: 'Systems programmer and full-stack builder. Interested in compilers, low-level architecture, and minimal interfaces that actually work.',
      researcher: 'Building AI/ML pipelines and literary corpora. Focus on natural language, BPE tokenization, and retrieval-augmented generation over historical texts.',
      creative: 'Fiction writer and constructed-language designer. Pen name: <strong>Auriel Solaris</strong>. Writes at the intersection of angelology, flood theology, and speculative horror.',
    },
  }));
});

